CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,full_name VARCHAR(150) NOT NULL,student_id VARCHAR(50) UNIQUE,email VARCHAR(255) UNIQUE,phone VARCHAR(40),academic_year VARCHAR(50),bio TEXT,avatar_url TEXT,profile_background_url TEXT,avatar_media_id BIGINT,cover_media_id BIGINT,profile_slug VARCHAR(100),privacy_settings JSONB NOT NULL DEFAULT '{"show_email":false,"show_phone":false,"show_online":true}',notification_settings JSONB NOT NULL DEFAULT '{"push":true,"announcements":true,"messages":true}',password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'member',is_active BOOLEAN NOT NULL DEFAULT TRUE,last_seen_at TIMESTAMPTZ,current_page VARCHAR(120) DEFAULT 'home',current_resource_type VARCHAR(60),current_resource_id BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_login TIMESTAMPTZ);
ALTER TABLE users ADD COLUMN IF NOT EXISTS phone VARCHAR(40);ALTER TABLE users ADD COLUMN IF NOT EXISTS academic_year VARCHAR(50);ALTER TABLE users ADD COLUMN IF NOT EXISTS bio TEXT;ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_media_id BIGINT;ALTER TABLE users ADD COLUMN IF NOT EXISTS cover_media_id BIGINT;ALTER TABLE users ADD COLUMN IF NOT EXISTS profile_slug VARCHAR(100);ALTER TABLE users ADD COLUMN IF NOT EXISTS privacy_settings JSONB NOT NULL DEFAULT '{"show_email":false,"show_phone":false,"show_online":true}';ALTER TABLE users ADD COLUMN IF NOT EXISTS notification_settings JSONB NOT NULL DEFAULT '{"push":true,"announcements":true,"messages":true}';ALTER TABLE users ADD COLUMN IF NOT EXISTS last_seen_at TIMESTAMPTZ;ALTER TABLE users ADD COLUMN IF NOT EXISTS current_page VARCHAR(120) DEFAULT 'home';ALTER TABLE users ADD COLUMN IF NOT EXISTS current_resource_type VARCHAR(60);ALTER TABLE users ADD COLUMN IF NOT EXISTS current_resource_id BIGINT;ALTER TABLE users ADD COLUMN IF NOT EXISTS last_login TIMESTAMPTZ;
CREATE TABLE IF NOT EXISTS media(id BIGSERIAL PRIMARY KEY,owner_id BIGINT REFERENCES users(id) ON DELETE CASCADE,mime_type VARCHAR(120) NOT NULL,file_name VARCHAR(255),byte_size INTEGER NOT NULL,data BYTEA NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE INDEX IF NOT EXISTS idx_media_owner ON media(owner_id,created_at DESC);
CREATE TABLE IF NOT EXISTS sessions(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());ALTER TABLE sessions ADD COLUMN IF NOT EXISTS session_type VARCHAR(20) NOT NULL DEFAULT 'member';ALTER TABLE sessions ADD COLUMN IF NOT EXISTS device_hash VARCHAR(64);ALTER TABLE sessions ADD COLUMN IF NOT EXISTS last_used_at TIMESTAMPTZ NOT NULL DEFAULT NOW();CREATE INDEX IF NOT EXISTS idx_sessions_user_exp ON sessions(user_id,expires_at DESC);
CREATE TABLE IF NOT EXISTS registrations(id BIGSERIAL PRIMARY KEY,full_name VARCHAR(150) NOT NULL,student_id VARCHAR(50) NOT NULL,year VARCHAR(50),academic_year VARCHAR(50),email VARCHAR(255),phone VARCHAR(40),note TEXT,password_hash TEXT,status VARCHAR(20) NOT NULL DEFAULT 'pending',reviewed_by BIGINT REFERENCES users(id) ON DELETE SET NULL,reviewed_at TIMESTAMPTZ,rejection_reason TEXT,user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,archived_at TIMESTAMPTZ,archived_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());ALTER TABLE registrations ADD COLUMN IF NOT EXISTS password_hash TEXT;CREATE INDEX IF NOT EXISTS idx_reg_status ON registrations(status,created_at DESC);
CREATE TABLE IF NOT EXISTS registration_checks(id BIGSERIAL PRIMARY KEY,registration_id BIGINT NOT NULL REFERENCES registrations(id) ON DELETE CASCADE,risk_level VARCHAR(20) NOT NULL,score INTEGER NOT NULL DEFAULT 0,flags JSONB NOT NULL DEFAULT '[]',details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS announcements(id BIGSERIAL PRIMARY KEY,title VARCHAR(255) NOT NULL,body TEXT NOT NULL,tag VARCHAR(50),is_published BOOLEAN NOT NULL DEFAULT TRUE,published_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE INDEX IF NOT EXISTS idx_announcements_pub ON announcements(is_published,published_at DESC);
CREATE TABLE IF NOT EXISTS activities(id BIGSERIAL PRIMARY KEY,title VARCHAR(255) NOT NULL,body TEXT NOT NULL,tag VARCHAR(50),event_date TIMESTAMPTZ,location VARCHAR(255),is_published BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());ALTER TABLE activities ADD COLUMN IF NOT EXISTS location VARCHAR(255);
CREATE TABLE IF NOT EXISTS schedules(id BIGSERIAL PRIMARY KEY,title VARCHAR(255) NOT NULL,body TEXT,day_name VARCHAR(30),start_time TIME,end_time TIME,room VARCHAR(100),is_published BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS posts(id BIGSERIAL PRIMARY KEY,author_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,section VARCHAR(40) NOT NULL DEFAULT 'community',title VARCHAR(255),body TEXT NOT NULL,body_html TEXT,content_type VARCHAR(20) NOT NULL DEFAULT 'post',hashtags TEXT[] NOT NULL DEFAULT '{}',image_url TEXT,media_id BIGINT,is_published BOOLEAN NOT NULL DEFAULT TRUE,is_pinned BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());ALTER TABLE posts ADD COLUMN IF NOT EXISTS body_html TEXT;ALTER TABLE posts ADD COLUMN IF NOT EXISTS content_type VARCHAR(20) NOT NULL DEFAULT 'post';ALTER TABLE posts ADD COLUMN IF NOT EXISTS hashtags TEXT[] NOT NULL DEFAULT '{}';ALTER TABLE posts ADD COLUMN IF NOT EXISTS media_id BIGINT;CREATE INDEX IF NOT EXISTS idx_posts_feed ON posts(section,is_published,is_pinned DESC,created_at DESC);CREATE INDEX IF NOT EXISTS idx_posts_tags ON posts USING GIN(hashtags);
CREATE TABLE IF NOT EXISTS post_likes(post_id BIGINT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(post_id,user_id));CREATE TABLE IF NOT EXISTS post_comments(id BIGSERIAL PRIMARY KEY,post_id BIGINT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,author_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE INDEX IF NOT EXISTS idx_comments_post ON post_comments(post_id,created_at);
CREATE TABLE IF NOT EXISTS conversations(id BIGSERIAL PRIMARY KEY,name VARCHAR(150),description TEXT,cover_image_url TEXT,cover_media_id BIGINT,hashtags TEXT[] NOT NULL DEFAULT '{}',type VARCHAR(30) NOT NULL DEFAULT 'direct',is_private BOOLEAN NOT NULL DEFAULT FALSE,created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,host_user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,messaging_paused BOOLEAN NOT NULL DEFAULT FALSE,voice_room_active BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());ALTER TABLE conversations ADD COLUMN IF NOT EXISTS cover_media_id BIGINT;ALTER TABLE conversations ADD COLUMN IF NOT EXISTS host_user_id BIGINT;ALTER TABLE conversations ADD COLUMN IF NOT EXISTS messaging_paused BOOLEAN NOT NULL DEFAULT FALSE;CREATE TABLE IF NOT EXISTS conversation_members(conversation_id BIGINT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role VARCHAR(20) NOT NULL DEFAULT 'member',joined_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),is_muted BOOLEAN NOT NULL DEFAULT FALSE,inbox_position_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_read_message_id BIGINT,PRIMARY KEY(conversation_id,user_id));ALTER TABLE conversation_members ADD COLUMN IF NOT EXISTS last_read_message_id BIGINT;CREATE INDEX IF NOT EXISTS idx_cm_user ON conversation_members(user_id,conversation_id);
CREATE TABLE IF NOT EXISTS messages(id BIGSERIAL PRIMARY KEY,conversation_id BIGINT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL DEFAULT '',image_url TEXT,audio_url TEXT,media_id BIGINT,audio_media_id BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),is_read BOOLEAN NOT NULL DEFAULT FALSE);ALTER TABLE messages ADD COLUMN IF NOT EXISTS media_id BIGINT;ALTER TABLE messages ADD COLUMN IF NOT EXISTS audio_media_id BIGINT;CREATE INDEX IF NOT EXISTS idx_messages_conv ON messages(conversation_id,created_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS user_notifications(id BIGSERIAL PRIMARY KEY,recipient_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,actor_id BIGINT REFERENCES users(id) ON DELETE SET NULL,kind VARCHAR(40) NOT NULL,title VARCHAR(255) NOT NULL,body TEXT,reference_type VARCHAR(40),reference_id BIGINT,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE INDEX IF NOT EXISTS idx_un_recipient ON user_notifications(recipient_id,created_at DESC);
CREATE TABLE IF NOT EXISTS reports(id BIGSERIAL PRIMARY KEY,reporter_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,target_type VARCHAR(40) NOT NULL,target_id BIGINT NOT NULL,reason VARCHAR(255) NOT NULL,details TEXT,status VARCHAR(20) NOT NULL DEFAULT 'open',reviewed_by BIGINT REFERENCES users(id) ON DELETE SET NULL,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE INDEX IF NOT EXISTS idx_reports_status ON reports(status,created_at DESC);
CREATE TABLE IF NOT EXISTS user_activity(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,current_page VARCHAR(120) NOT NULL DEFAULT 'home',resource_type VARCHAR(60),resource_id BIGINT,last_activity_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE INDEX IF NOT EXISTS idx_activity_recent ON user_activity(last_activity_at DESC);
CREATE TABLE IF NOT EXISTS activity_events(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,page VARCHAR(120) NOT NULL,event_type VARCHAR(80) NOT NULL DEFAULT 'interaction',resource_type VARCHAR(60),resource_id BIGINT,metadata JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE INDEX IF NOT EXISTS idx_events_user ON activity_events(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS app_settings(key VARCHAR(120) PRIMARY KEY,value JSONB NOT NULL DEFAULT '{}',updated_by BIGINT REFERENCES users(id) ON DELETE SET NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,actor_user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,action VARCHAR(120) NOT NULL,target_type VARCHAR(60),target_id BIGINT,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE INDEX IF NOT EXISTS idx_audit_recent ON audit_logs(created_at DESC);
CREATE TABLE IF NOT EXISTS agent_actions(id BIGSERIAL PRIMARY KEY,actor_user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,action_type VARCHAR(120) NOT NULL,target_type VARCHAR(60),target_id BIGINT,details JSONB NOT NULL DEFAULT '{}',status VARCHAR(30) NOT NULL DEFAULT 'completed',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_sanctions(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,kind VARCHAR(30) NOT NULL,reason TEXT,device_hash VARCHAR(64),expires_at TIMESTAMPTZ,created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS polls(id BIGSERIAL PRIMARY KEY,author_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,question TEXT NOT NULL,options JSONB NOT NULL DEFAULT '[]',hashtags TEXT[] NOT NULL DEFAULT '{}',duration_minutes INTEGER NOT NULL DEFAULT 1440,closes_at TIMESTAMPTZ,allow_vote_change BOOLEAN NOT NULL DEFAULT TRUE,anonymous BOOLEAN NOT NULL DEFAULT FALSE,results_visibility VARCHAR(20) NOT NULL DEFAULT 'after_vote',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE TABLE IF NOT EXISTS poll_votes(poll_id BIGINT NOT NULL REFERENCES polls(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,option_index INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(poll_id,user_id));
INSERT INTO app_settings(key,value) VALUES('theme','{"background":"#101116","surface":"#17181f","surface2":"#1e2028","accent":"#7b61ff","accent2":"#9b88ff","gold":"#d5b56a","logo":"/assets/icon.png","community_name":"اتحاد طلبة كلية القانون"}'::jsonb) ON CONFLICT(key) DO NOTHING;INSERT INTO app_settings(key,value) VALUES('features','{"chat":true,"posts":true,"polls":true,"activities":true,"notifications":true,"presence":true,"assistant":true}'::jsonb) ON CONFLICT(key) DO NOTHING;
INSERT INTO conversations(name,type,is_private) SELECT 'الغرفة العامة','official',false WHERE NOT EXISTS(SELECT 1 FROM conversations WHERE type='official' AND name='الغرفة العامة');